#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define SPATIAL_TILE 4
__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int N,
    const int C_in,
    const int D_in,
    const int H_in,
    const int W_in,
    const int C_out,
    const int D_out,
    const int H_out,
    const int W_out,
    const int kD,
    const int kH,
    const int kW,
    const int stride_d,
    const int stride_h,
    const int stride_w,
    const int pad_d,
    const int pad_h,
    const int pad_w,
    const int groups,
    const int C_in_per_group,
    const int C_out_per_group,
    const bool has_bias
) {
    // Double-buffered shared memory staging: overlap the load of the next kernel
    // tap with the compute of the current tap, reducing synchronization from
    // two __syncthreads() per tap down to one.
    extern __shared__ float smem_raw[];
    const int tile_elems = SPATIAL_TILE * C_in_per_group;
    const int weight_elems = C_in_per_group * C_out_per_group;
    float* smem_input_buf[2];
    float* smem_weight_buf[2];
    smem_input_buf[0]  = smem_raw;
    smem_input_buf[1]  = smem_raw + tile_elems;
    smem_weight_buf[0] = smem_raw + 2 * tile_elems;
    smem_weight_buf[1] = smem_raw + 2 * tile_elems + weight_elems;
    const int linear_tid = threadIdx.y * blockDim.x + threadIdx.x;
    const int total_threads_block = blockDim.x * blockDim.y;
    const long total_spatial = (long)N * D_out * H_out * W_out;
    const int tile_id = threadIdx.y;
    const int totalK = kD * kH * kW;
    const int kHW = kH * kW;
    for (long sidx0 = (long)blockIdx.x * SPATIAL_TILE; sidx0 < total_spatial; sidx0 += (long)gridDim.x * SPATIAL_TILE) {
        long sidx = sidx0 + tile_id;
        const bool valid = sidx < total_spatial;
        long safe_sidx = valid ? sidx : sidx0;
        long tmp = safe_sidx;
        const int ow = tmp % W_out; tmp /= W_out;
        const int oh = tmp % H_out; tmp /= H_out;
        const int od = tmp % D_out; tmp /= D_out;
        const int n  = tmp;
        for (int group_id = 0; group_id < groups; group_id++) {
            const int ic_start = group_id * C_in_per_group;
            const int oc_base  = group_id * C_out_per_group;
            const bool active = valid && ((int)threadIdx.x < C_out_per_group);
            float acc = 0.0f;
            // Load first tap (kidx = 0) into buffer 0.
            {
                const int kd = 0, kh = 0, kw = 0;
                int id_nom = od + pad_d - kd;
                bool d_ok = (id_nom >= 0) && (id_nom % stride_d == 0);
                int id = d_ok ? id_nom / stride_d : 0;
                if (d_ok && (id < 0 || id >= D_in)) d_ok = false;
                int ih_nom = oh + pad_h - kh;
                bool h_ok = d_ok && (ih_nom >= 0) && (ih_nom % stride_h == 0);
                int ih = h_ok ? ih_nom / stride_h : 0;
                if (h_ok && (ih < 0 || ih >= H_in)) h_ok = false;
                int iw_nom = ow + pad_w - kw;
                bool w_ok = h_ok && (iw_nom >= 0) && (iw_nom % stride_w == 0);
                int iw = w_ok ? iw_nom / stride_w : 0;
                if (w_ok && (iw < 0 || iw >= W_in)) w_ok = false;
                const bool do_load = valid && w_ok;
                float* tile_buf = smem_input_buf[0] + tile_id * C_in_per_group;
                for (int icg = threadIdx.x; icg < C_in_per_group; icg += blockDim.x) {
                    if (do_load) {
                        int ic = ic_start + icg;
                        long input_idx = (((long)n * C_in + ic) * D_in + id) * H_in * W_in
                                          + (long)ih * W_in + iw;
                        tile_buf[icg] = input[input_idx];
                    } else {
                        tile_buf[icg] = 0.0f;
                    }
                }
                float* weight_buf = smem_weight_buf[0];
                for (int widx = linear_tid; widx < weight_elems; widx += total_threads_block) {
                    int icg_w = widx / C_out_per_group;
                    int oc_w = widx % C_out_per_group;
                    int ic_w = ic_start + icg_w;
                    long weight_idx_w = (((long)ic_w * C_out_per_group + oc_w) * kD + kd) * kH * kW
                                         + (long)kh * kW + kw;
                    weight_buf[widx] = weight[weight_idx_w];
                }
            }
            __syncthreads();
            for (int kidx = 0; kidx < totalK; kidx++) {
                const int cur = kidx & 1;
                const int nxt = cur ^ 1;
                if (kidx + 1 < totalK) {
                    const int kidx2 = kidx + 1;
                    const int kd = kidx2 / kHW;
                    const int rem = kidx2 % kHW;
                    const int kh = rem / kW;
                    const int kw = rem % kW;
                    int id_nom = od + pad_d - kd;
                    bool d_ok = (id_nom >= 0) && (id_nom % stride_d == 0);
                    int id = d_ok ? id_nom / stride_d : 0;
                    if (d_ok && (id < 0 || id >= D_in)) d_ok = false;
                    int ih_nom = oh + pad_h - kh;
                    bool h_ok = d_ok && (ih_nom >= 0) && (ih_nom % stride_h == 0);
                    int ih = h_ok ? ih_nom / stride_h : 0;
                    if (h_ok && (ih < 0 || ih >= H_in)) h_ok = false;
                    int iw_nom = ow + pad_w - kw;
                    bool w_ok = h_ok && (iw_nom >= 0) && (iw_nom % stride_w == 0);
                    int iw = w_ok ? iw_nom / stride_w : 0;
                    if (w_ok && (iw < 0 || iw >= W_in)) w_ok = false;
                    const bool do_load = valid && w_ok;
                    float* tile_buf = smem_input_buf[nxt] + tile_id * C_in_per_group;
                    for (int icg = threadIdx.x; icg < C_in_per_group; icg += blockDim.x) {
                        if (do_load) {
                            int ic = ic_start + icg;
                            long input_idx = (((long)n * C_in + ic) * D_in + id) * H_in * W_in
                                              + (long)ih * W_in + iw;
                            tile_buf[icg] = input[input_idx];
                        } else {
                            tile_buf[icg] = 0.0f;
                        }
                    }
                    float* weight_buf = smem_weight_buf[nxt];
                    for (int widx = linear_tid; widx < weight_elems; widx += total_threads_block) {
                        int icg_w = widx / C_out_per_group;
                        int oc_w = widx % C_out_per_group;
                        int ic_w = ic_start + icg_w;
                        long weight_idx_w = (((long)ic_w * C_out_per_group + oc_w) * kD + kd) * kH * kW
                                             + (long)kh * kW + kw;
                        weight_buf[widx] = weight[weight_idx_w];
                    }
                }
                if (active) {
                    float* tile_buf = smem_input_buf[cur] + tile_id * C_in_per_group;
                    float* weight_buf = smem_weight_buf[cur];
                    const int oc_in_group = threadIdx.x;
                    #pragma unroll 4
                    for (int icg = 0; icg < C_in_per_group; icg++) {
                        acc += tile_buf[icg] * weight_buf[icg * C_out_per_group + oc_in_group];
                    }
                }
                __syncthreads();
            }
            if (active) {
                int oc = oc_base + threadIdx.x;
                if (has_bias) {
                    acc += bias[oc];
                }
                long out_idx = (((long)n * C_out + oc) * D_out + od) * H_out * W_out
                                + (long)oh * W_out + ow;
                output[out_idx] = acc;
            }
        }
    }
}
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int outpad_d, int outpad_h, int outpad_w,
    int groups
) {
    input = input.contiguous();
    weight = weight.contiguous();
    const int N = input.size(0);
    const int C_in = input.size(1);
    const int D_in = input.size(2);
    const int H_in = input.size(3);
    const int W_in = input.size(4);
    const int C_out_per_group = weight.size(1);
    const int C_out = C_out_per_group * groups;
    const int kD = weight.size(2);
    const int kH = weight.size(3);
    const int kW = weight.size(4);
    const int C_in_per_group = C_in / groups;
    const int D_out = (D_in - 1) * stride_d - 2 * pad_d + kD + outpad_d;
    const int H_out = (H_in - 1) * stride_h - 2 * pad_h + kH + outpad_h;
    const int W_out = (W_in - 1) * stride_w - 2 * pad_w + kW + outpad_w;
    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());
    bool has_bias = bias.defined() && bias.numel() > 0;
    const long total_spatial = (long)N * D_out * H_out * W_out;
    int max_dim = C_in_per_group > C_out_per_group ? C_in_per_group : C_out_per_group;
    int threads_x = ((max_dim + 31) / 32) * 32;
    if (threads_x < 32) threads_x = 32;
    if (threads_x > 256) threads_x = 256;
    dim3 threads(threads_x, SPATIAL_TILE);
    long total_tiles = (total_spatial + SPATIAL_TILE - 1) / SPATIAL_TILE;
    long blocks_l = std::min(total_tiles, (long)250000);
    const int blocks = (int)blocks_l;
    const size_t smem_bytes = (size_t)(2 * (SPATIAL_TILE * C_in_per_group) + 2 * (C_in_per_group * C_out_per_group)) * sizeof(float);
    conv_transpose3d_kernel<<<blocks, threads, smem_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        N, C_in, D_in, H_in, W_in,
        C_out, D_out, H_out, W_out,
        kD, kH, kW,
        stride_d, stride_h, stride_w,
        pad_d, pad_h, pad_w,
        groups,
        C_in_per_group,
        C_out_per_group,
        has_bias
    );
    return output;
}
